parameters.jsCode:
// Replyze signs only the raw body: X-Replyze-Signature is "sha256=" and the hex
// HMAC-SHA256 of the exact bytes received, keyed with this webhook's signing
// secret. "Sign the raw body" computed that HMAC over the same bytes.
// X-Replyze-Timestamp and X-Replyze-Event-Id are unsigned copies of the body's
// created_at and id: anyone who captured a request can send it again with new
// values in them. So this node reads the time and the id from the signed body.
const MAX_AGE_SECONDS = 300;

const item = $input.first().json;
const answer = (status, handle, response, extra = {}) => [{ json: { status, handle, response, ...extra } }];

// 1. The signature, compared as bytes and in constant time: every byte of the
//    expected value is checked, whatever the first difference.
const bytes = (text) => new TextEncoder().encode(text);
const expected = bytes('sha256=' + item.expectedSignature);
const header = (item.headers || {})['x-replyze-signature'];
const given = typeof header === 'string' ? bytes(header) : new Uint8Array(0);
let difference = expected.length ^ given.length;
for (let i = 0; i < expected.length; i++) {
  difference |= expected[i] ^ (i < given.length ? given[i] : 0);
}
if (difference !== 0) {
  return answer(401, false, { error: 'The signature does not match.' });
}

// 2. Signed, so the body can be trusted: parse the exact bytes that were
//    signed ("Raw body") and take the time from them.
let event = null;
try {
  event = JSON.parse(item.rawBody);
} catch (error) {
  event = null;
}
const now = Date.now();
const sentAt = event && typeof event.created_at === 'string' ? Date.parse(event.created_at) : NaN;
if (!Number.isFinite(sentAt) || Math.abs(now - sentAt) > MAX_AGE_SECONDS * 1000) {
  return answer(400, false, { error: 'Too old: the event was not created in the last ' + MAX_AGE_SECONDS + ' seconds.' });
}

// 3. The id, from the body too. An event this workflow has already taken
//    (Replyze's retry, or a replay) gets 200 and goes no further. The ids are
//    kept in the workflow's static data for as long as step 2 would let the
//    event in. n8n saves static data when a run of the published workflow ends.
const id = typeof event.id === 'string' ? event.id : '';
if (id === '') {
  return answer(400, false, { error: 'The event has no id.' });
}
const memory = $getWorkflowStaticData('global');
const seen = {};
for (const [key, until] of Object.entries(memory.replyzeEventIds || {})) {
  if (until >= now) seen[key] = until;
}
if (Object.prototype.hasOwnProperty.call(seen, id)) {
  return answer(200, false, { received: true, duplicate: true }, { eventId: id });
}
seen[id] = sentAt + MAX_AGE_SECONDS * 1000;
memory.replyzeEventIds = seen;

return answer(200, true, { received: true }, { eventId: id, body: event });

// The webhook's body: { id, event, created_at, workspace_id, data }.
// message.created carries data.message and data.conversation.
const body = $input.first().json.body || {};
const message = (body.data && body.data.message) || {};
const conversation = (body.data && body.data.conversation) || {};
const text = typeof message.content === 'string' ? message.content.trim() : '';
const createdAt = Date.parse(message.created_at || body.created_at) || Date.now();

return [{
  json: {
    event: body.event,
    eventId: body.id,
    conversationId: conversation.id || message.conversation_id || null,
    messageId: message.id || null,
    senderType: message.sender_type || null,
    text,
    channel: conversation.channel || null,
    // Only the visitor's own words get an answer. Replies from the team, from
    // Replyze's AI and from this workflow (sent through the API, so
    // sender_type "agent") are ignored: that is what stops a reply loop.
    // Images, files and voice notes (type "image", "file"...) wait for the team.
    fromVisitor: body.event === 'message.created' && message.sender_type === 'visitor' && message.type === 'text' && text !== '',
    historySince: new Date(createdAt - 24 * 3600 * 1000).toISOString(),
    checkSince: new Date(createdAt - 60 * 1000).toISOString(),
  },
}];

// Steps back whenever a person has the conversation, so the AI never talks over your team.
const event = $('Settings').first().json; // the event's fields and your settings
const conversation = $('Get the conversation').first().json;
// "Get recent messages" gives one item per page, oldest first. If the last page
// still says has_more, the newest messages weren't read: better to stay out.
const pages = $input.all().map((item) => item.json);
const messages = pages.flatMap((page) => page.data || []);
const readAll = pages.length > 0 && pages[pages.length - 1].has_more === false;
const handoffTag = String(event.handoffTag || '').trim().toLowerCase();

const teammateReplied = messages.some((m) => m.sender_type === 'agent' && m.sender && !m.is_internal_note);
const newer = messages.filter((m) => m.id > event.messageId);

let skipReason = null;
if (conversation.status !== 'open') {
  skipReason = 'The conversation is ' + conversation.status + '.';
} else if (handoffTag && (conversation.tags || []).some((t) => String(t.name).toLowerCase() === handoffTag)) {
  skipReason = 'The conversation has the "' + event.handoffTag + '" tag: the team has it.';
} else if (event.stopWhenAssigned && conversation.assigned_agent) {
  skipReason = 'The conversation is assigned to ' + conversation.assigned_agent.name + '.';
} else if (!readAll) {
  skipReason = 'More than ' + messages.length + ' messages in the last 24 hours: too many to read, so the team answers.';
} else if (teammateReplied) {
  skipReason = 'A teammate has replied in this conversation.';
} else if (newer.some((m) => m.sender_type === 'visitor')) {
  skipReason = 'The visitor wrote again: the run for the newest message answers.';
} else if (newer.some((m) => (m.sender_type === 'agent' || m.sender_type === 'bot') && !m.is_internal_note)) {
  skipReason = 'This message already has an answer.';
}

// The conversation so far, for the agent: the last 20 messages before this one.
const who = (m) => m.sender_type === 'visitor' ? 'Customer'
  : m.sender_type === 'bot' ? 'Support (AI)'
  : m.sender ? 'Support (' + m.sender.name + ')' : 'Support';
const history = messages
  .filter((m) => m.id < event.messageId && !m.is_internal_note && typeof m.content === 'string' && m.content.trim() !== '')
  .slice(-20)
  .map((m) => who(m) + ': ' + m.content.trim())
  .join('\n');

return [{
  json: {
    answer: skipReason === null,
    skipReason,
    conversationId: event.conversationId,
    messageId: event.messageId,
    question: event.text,
    history,
    checkSince: event.checkSince,
  },
}];

