// The handoff itself (tag, note, assignment) happens after the agent, in
// the nodes under "Hand off?". This only tells the agent it worked.
return 'Done: the conversation is now with the team. Tell the customer that a teammate will reply here soon.';

// The agent's reply, and whether it called hand_off_to_human.
// This node also receives the agent's error output: when the model fails or
// says nothing, the visitor gets your fallback reply and the team gets the chat.
const asked = $('Should the AI answer?').first().json;
const settings = $('Settings').first().json;
const result = $input.first().json;

const steps = Array.isArray(result.intermediateSteps) ? result.intermediateSteps : [];
const handoffStep = steps.find((s) => s && s.action && s.action.tool === 'hand_off_to_human');
const inputText = (input) => typeof input === 'string' ? input
  : input && typeof input === 'object' ? String(input.input || input.query || input.reason || JSON.stringify(input))
  : '';

let reply = typeof result.output === 'string' ? result.output.trim() : '';
let handoff = Boolean(handoffStep);
let reason = handoffStep ? inputText(handoffStep.action.toolInput) : '';

if (!reply) {
  const error = result.error ? (result.error.message || String(result.error)) : '';
  handoff = true;
  reason = error ? 'The AI agent failed: ' + error : 'The AI agent gave no answer.';
  reply = settings.fallbackReply;
}

return [{
  json: {
    conversationId: asked.conversationId,
    messageId: asked.messageId,
    reply,
    handoff,
    reason: handoff ? (reason || 'The AI agent handed it over.') : null,
    checkSince: asked.checkSince,
  },
}];

// The model took a few seconds. Before anything goes out, make sure nobody
// answered meanwhile (Replyze's AI, a teammate, or another run of this
// workflow for a retried event) and that the visitor didn't write again.
const answer = $('Agent answer').first().json;
const pages = $input.all().map((item) => item.json);
const readAll = pages.length > 0 && pages[pages.length - 1].has_more === false;
const newer = pages.flatMap((page) => page.data || []).filter((m) => m.id > answer.messageId);
const visitorAgain = newer.some((m) => m.sender_type === 'visitor');
const answered = newer.some((m) => (m.sender_type === 'agent' || m.sender_type === 'bot') && !m.is_internal_note);

return [{
  json: {
    ...answer,
    send: readAll && !visitorAgain && !answered,
    skipReason: !readAll ? 'Too many new messages to check.'
      : visitorAgain ? 'The visitor wrote again while the agent was answering.'
      : answered ? 'Someone answered while the agent was answering.' : null,
  },
}];
